using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Web.Script.Serialization;using DualSteam.UI;using DualSteam;
public partial class App {
 TextBlock updatesStatus,updateDetail,updateChecked;ProgressBar updateProgress;Button updateCheckButton,updateInstallButton;readonly UpdateFeedback updateFeedback=new UpdateFeedback();ReleaseInfo availableRelease;bool checkingUpdates;DateTime nextUpdate=DateTime.MinValue;string notifiedVersion;
 void BeginSetup(){if(!ServiceReady())return;var wizard=new SetupWizard(Engine.DetectSteam()){Owner=window};if(wizard.ShowDialog()==true)Act(()=>SetupService.Provision(wizard.SteamPath,wizard.DataPath),"Second Steam is ready. Open it and sign in to your second account.",secondCard);}
 void UpdateFeedbackView(){if(updatesStatus==null)return;updatesStatus.Text=updateFeedback.Title;updateDetail.Text=updateFeedback.Detail;updateChecked.Text=updateFeedback.LastChecked.HasValue?"Last checked: "+updateFeedback.LastChecked.Value.ToString("G"):"Not checked in this session";updateProgress.Visibility=checkingUpdates?Visibility.Visible:Visibility.Collapsed;updateCheckButton.Content=checkingUpdates?"Checking…":"Check for updates";updateCheckButton.IsEnabled=!checkingUpdates&&!busy;updateInstallButton.IsEnabled=availableRelease!=null&&!checkingUpdates&&!busy;}
 async void CheckUpdates(bool manual=false){
  if(manual){ShowManager();if(page!="Updates")ShowPage("Updates");}
  if(checkingUpdates)return;if(busy){if(manual)toast.Show("Wait for the current operation to finish.");return;}
  checkingUpdates=true;nextUpdate=DateTime.UtcNow.AddMinutes(30);availableRelease=null;updateFeedback.Begin();UpdateFeedbackView();
  try{var request=Task.Run(()=>UpdateService.GetLatest());if(manual)await Task.WhenAll(request,Task.Delay(700));var release=await request;availableRelease=release.Version>UpdateService.ParseVersion(UpdateService.CurrentVersion)?release:null;nextUpdate=DateTime.UtcNow.AddHours(6);updateFeedback.Complete(UpdateService.ParseVersion(UpdateService.CurrentVersion),release.Version);
   if(!manual&&availableRelease!=null&&notifiedVersion!=release.Tag){notifiedVersion=release.Tag;ShowManager();if(page!="Updates")ShowPage("Updates");if(AppDialog.Show(window,"Version "+release.Tag+" is available. Your accounts and game files will be preserved.\n\nDownload and install this update? Quit Second Steam first.","Dual Steam update",MessageBoxButton.YesNo,MessageBoxImage.Information)==MessageBoxResult.Yes){var pendingInstall=Dispatcher.BeginInvoke(new Action(InstallUpdate));}}
  }catch(Exception ex){availableRelease=null;updateFeedback.Fail(ex.Message);Engine.Log("Update check: "+ex.Message);}finally{if(!startupAuthorized&&serviceDecision=="update"&&startupPolicy!=null&&startupPolicy.Release!=null){var required=startupPolicy.Release;availableRelease=new ReleaseInfo{Tag=required.Tag,Version=ServicePolicy.Version(startupPolicy.RequiredVersion),Page="https://github.com/"+UpdateService.Repository+"/releases/tag/"+required.Tag,Download=required.Url,Sha256=required.Sha256,Size=required.Size};updateFeedback.Title="Update required";updateFeedback.Detail="Install "+startupPolicy.RequiredVersion+" to authorize this startup.";}checkingUpdates=false;UpdateFeedbackView();}
 }
 async void InstallUpdate(){if(busy||checkingUpdates)return;if(availableRelease==null){CheckUpdates(true);return;}busy=true;UpdateFeedbackView();try{var release=availableRelease;await Task.Run(()=>{if(Engine.Current!=null){var status=Engine.Status();if((status.RootIds??new int[0]).Length>0||(status.GameIds??new int[0]).Length>0)throw new IOException("Quit Second Steam and its games before installing the update. Main Steam can stay open.");try{Engine.Control("detach");}catch(System.TimeoutException){}}});if(updatesStatus!=null)updatesStatus.Text="Downloading and verifying the update…";string package=await Task.Run(()=>UpdateService.Download(release));string folder=Path.GetDirectoryName(package);var request=new UpdateRequest{Target=Engine.Home,Package=package,Sha256=release.Sha256,Version=release.Version.ToString(),ManagerPid=Process.GetCurrentProcess().Id,ManagerStartTicks=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks};string file=Path.Combine(folder,"request.json");File.WriteAllText(file,new JavaScriptSerializer().Serialize(request));string updater=Path.Combine(folder,"Dual Steam Updater.exe");File.Copy(Path.Combine(Engine.Home,"Dual Steam Updater.exe"),updater);Process.Start(new ProcessStartInfo(updater,"--request "+Engine.Quote(file)){UseShellExecute=true});ShutdownManager();}catch(Exception ex){Engine.Log("Update install: "+ex);AppDialog.Show(window,ex.Message,"Update not installed",MessageBoxButton.OK,MessageBoxImage.Information);}finally{busy=false;UpdateFeedbackView();}}
 FrameworkElement UpdatesPage(){
  var body=Stack();Heading("Updates","Stable releases from GitHub. Your profiles stay in place.",body);
  updatesStatus=Text(updateFeedback.Title,18,"text.primary",true);updateDetail=Text(updateFeedback.Detail,13,"text.secondary");updateDetail.Margin=new Thickness(0,8,0,0);updateChecked=Text("",12,"text.muted");updateChecked.Margin=new Thickness(0,12,0,0);updateProgress=new ProgressBar{IsIndeterminate=true,Height=4,Margin=new Thickness(0,16,0,0)};Theme.Bind(updateProgress,Control.ForegroundProperty,"accent.default");Ui.Name(updateProgress,"Checking GitHub for updates");System.Windows.Automation.AutomationProperties.SetAutomationId(updateProgress,"UpdateCheckProgress");System.Windows.Automation.AutomationProperties.SetAutomationId(updatesStatus,"UpdateResult");System.Windows.Automation.AutomationProperties.SetAutomationId(updateChecked,"UpdateLastChecked");body.Children.Add(Group(updatesStatus,updateDetail,updateChecked,updateProgress));
  body.Children.Add(Choice("Notify me about updates during this session",Preferences.Current.AutoUpdates,v=>Preferences.Current.AutoUpdates=v));body.Children.Add(Text("Every stable public release is required at the next full startup. Startup availability is always checked, even if notifications are disabled. Open sessions continue working. Optional checks run every six hours. Downloads are checked against GitHub’s SHA-256 digest and backed up before installation.",13,"text.secondary"));
  var actions=new WrapPanel();updateCheckButton=ActionButton("Check for updates",()=>CheckUpdates(true),true);Ui.Name(updateCheckButton,"Check for updates");System.Windows.Automation.AutomationProperties.SetAutomationId(updateCheckButton,"UpdateCheckButton");updateCheckButton.Margin=new Thickness(0,16,8,8);actions.Children.Add(updateCheckButton);updateInstallButton=ActionButton("Install update",InstallUpdate);updateInstallButton.Margin=new Thickness(0,16,0,8);actions.Children.Add(updateInstallButton);body.Children.Add(actions);body.Children.Add(ActionButton("View releases on GitHub",()=>OpenPath("https://github.com/"+UpdateService.Repository+"/releases")));UpdateFeedbackView();return body;
 }
 FrameworkElement AddonOptions(){var body=Stack();if(!MillenniumSharing.Detected){if(MillenniumSharing.CanDisable)body.Children.Add(ActionButton("Disable imported Millennium runtime",()=>Act(MillenniumSharing.Disable,"Imported Millennium disabled. Themes and backups were preserved.")));return body;}var choices=Stack();choices.Children.Add(Text("MILLENNIUM DETECTED",12,"text.muted",true));choices.Children.Add(Text("Import only the components you select. Quit Second Steam first. Add-ons run code inside Steam and may affect compatibility.",13,"text.secondary"));choices.Children.Add(Choice("Millennium runtime",Preferences.Current.ImportMillennium,v=>Preferences.Current.ImportMillennium=v));if(MillenniumSharing.ThemesDetected)choices.Children.Add(Choice("Installed themes",Preferences.Current.ImportThemes,v=>Preferences.Current.ImportThemes=v));if(MillenniumSharing.ConfigDetected)choices.Children.Add(Choice("Theme selection, appearance settings and custom CSS",Preferences.Current.ImportThemeSettings,v=>Preferences.Current.ImportThemeSettings=v));if(MillenniumSharing.PluginsDetected)choices.Children.Add(Choice("Installed plugins and enabled-plugin list",Preferences.Current.ImportPlugins,v=>Preferences.Current.ImportPlugins=v));choices.Children.Add(Choice("Import these selections before Second Steam starts",Preferences.Current.SyncMillennium,v=>Preferences.Current.SyncMillennium=v));choices.Children.Add(ActionButton("Import selected add-ons",()=>Act(()=>{Engine.LastLaunchNotice=MillenniumSharing.Import();},"Selected add-ons imported."),true));choices.Children.Add(Text("Steam credentials, account data, proxy credentials and unrelated loader DLLs are excluded. Originals are backed up under Backups / Millennium.",12,"text.muted"));if(MillenniumSharing.CanDisable)choices.Children.Add(ActionButton("Disable imported Millennium runtime",()=>Act(MillenniumSharing.Disable,"Imported Millennium disabled. Themes and backups were preserved.")));body.Children.Add(Group(choices));return body;}
